if(args.Length!=1)return 2;
string root=Path.GetFullPath(args[0]);
string Read(string n)=>File.ReadAllText(Path.Combine(root,"content/generated",n,"catalog.json"));
var legacy=PretRoute22Pokemon.LoadContent(Read("route1-pokemon"),Read("old-man-tutorial"),Read("forest-pokemon"),Read("pewter-pokemon"),Read("route22-pokemon")).Catalog;
var catalog=PretRoute3Pokemon.LoadContent(Read("route1-pokemon"),Read("old-man-tutorial"),Read("forest-pokemon"),Read("pewter-pokemon"),Read("route22-pokemon"),Read("route3-pokemon")).Catalog;
const string profile=WildBattleRules.Route3RulesVersion;
int checks=0,failures=0;var results=new List<object>();
void Check(bool b,string why){checks++;if(!b)throw new Exception(why);}
void Test(string n,Action a){try{a();results.Add(new{name=n,passed=true});}catch(Exception e){failures++;results.Add(new{name=n,passed=false,error=e.ToString()});}}
MoveId Move(string n)=>new("pret:MOVE_"+n);
PokemonInstance Mon(string species="RATICATE",int level=20,uint pid=200)=>PokemonFactory.Create(catalog,new(new("pret:SPECIES_"+species),level,1,IvPolicy.Fixed(0),PersonalityPolicy.Fixed(pid)),new(0)).Pokemon;
PokemonInstance Moves(PokemonInstance p,params string[] names)=>p with{Moves=names.Select(n=>{var m=catalog.Moves[Move(n)];return new PokemonMoveSlot(m.Id,m.Pp,m.Pp);}).ToImmutableArray()};
WildBattleState Pair(string move,uint seed=0,string actor="RATICATE",string target="GEODUDE",string reply="SPLASH")=>new(new(Moves(Mon(actor),move)),new(Moves(Mon(target),reply)),2,4,10,new(seed),123,WildBattleOutcome.Ongoing,RulesVersion:profile);
WildBattleState Accepted(WildBattleResult r){Check(r.Succeeded,r.Fault??"fault");Check(WildBattleRules.Validate(catalog,r.State)==null,WildBattleRules.Validate(catalog,r.State)??"invalid");return r.State!;}
void Atomic(WildBattleState s,WildBattleResult r)=>Check(!r.Succeeded&&ReferenceEquals(s,r.State)&&r.Events.IsEmpty&&r.Trace.IsEmpty,"non-atomic fault");
WildBattleResult Seeded(Func<uint,WildBattleResult> action,Func<WildBattleResult,bool> predicate){for(uint seed=0;seed<256;seed++){var r=action(seed);if(r.Succeeded&&predicate(r))return r;}throw new Exception("No branch seed");}
Test("production40-53-moves-frozen-json",()=>{
 Check(catalog.Species.Count==40&&legacy.Species.Count==32,"catalog");Check(catalog.Moves.Keys.Count(m=>WildBattleRules.IsMoveSupported(m,profile))==53,"moves");
 foreach(var n in new[]{"POUND","DOUBLE_KICK","HORN_ATTACK","WRAP","SING","DISABLE","GLARE","SPLASH","ROLLOUT"})Check(!WildBattleRules.IsMoveSupported(Move(n),WildBattleRules.Route22RulesVersion),"legacy expanded");
 Check(!WildBattleRules.IsMoveSupported(Move("THRASH"),profile),"Thrash unexpectedly enabled");
 var s=Pair("TACKLE",reply:"DEFENSE_CURL") with{RulesVersion=WildBattleRules.Route22RulesVersion};Check(JsonSerializer.Serialize(WildBattleRules.ResolveMove(legacy,s,0))==JsonSerializer.Serialize(WildBattleRules.ResolveMove(catalog,s,0)),"legacy bytes");
 var json=JsonSerializer.Serialize(s.Player);Check(!json.Contains("LastUsedMove")&&!json.Contains("Rollout")&&!json.Contains("Disable")&&!json.Contains("Infatuation")&&!json.Contains("BindingMove"),"default fields emitted");
});
foreach(var n in new[]{"POUND","DOUBLE_KICK","HORN_ATTACK","WRAP","SING","DISABLE","GLARE","SPLASH","ROLLOUT"})Test(n+"-source-definition-atomic",()=>{
 var s=Pair(n);Accepted(WildBattleRules.ResolveMove(catalog,s,0));var m=catalog.Moves[Move(n)];foreach(var bad in new[]{m with{Accuracy=m.Accuracy+1},m with{Flags=m.Flags.Add("FLAG_FAKE")},m with{SourceMoveId=300}})Atomic(s,WildBattleRules.ResolveMove(catalog with{Moves=catalog.Moves.SetItem(bad.Id,bad)},s,0));
 var overflow=s with{Rng=new(0,ulong.MaxValue-1)};Atomic(overflow,WildBattleRules.ResolveMove(catalog,overflow,0));
});
Test("wrap-counter-identity-expiry-faint-source-left",()=>{
 var r=Seeded(seed=>WildBattleRules.ResolveMove(catalog,Pair("WRAP",seed,target:"RATICATE"),0),x=>x.Events.OfType<WildBattleBindingDamageEvent>().Any());var after=Accepted(r);var applied=r.Events.OfType<WildBattleBindingChangedEvent>().First();var damage=r.Events.OfType<WildBattleBindingDamageEvent>().Single();
 Check(applied.Move==Move("WRAP")&&applied.After is >=3 and <=6&&damage.Remaining==applied.After-1&&damage.Move==Move("WRAP"),"source Wrap counter");
 var switched=WildBattleRules.SwitchPlayer(catalog,after,new(Moves(Mon("PIDGEY"),"TACKLE")),true);Accepted(switched);Check(switched.Events.OfType<WildBattleBindingChangedEvent>().Single(e=>e.Reason=="source-left").Move==Move("WRAP"),"source-left identity");
 foreach(bool faint in new[]{false,true}){var s=Pair("SPLASH");s=s with{Opponent=s.Opponent with{BindTurnsRemaining=faint?3:1,BindingMove=Move("WRAP"),Pokemon=faint?s.Opponent.Pokemon with{CurrentHp=1}:s.Opponent.Pokemon}};var result=WildBattleRules.ResolveMove(catalog,s,0);var end=Accepted(result);var e=result.Events.OfType<WildBattleBindingChangedEvent>().Single(x=>x.Reason==(faint?"faint":"expired"));Check(e.Move==Move("WRAP")&&end.Opponent.BindingMove is null&&end.Opponent.BindTurnsRemaining==0,"clear identity");}
 var old=new WildBattleBindingChangedEvent(1,2,WildBattleSide.Opponent,1,0,"expired");var json=JsonSerializer.Serialize<WildBattleEvent>(old);Check(!json.Contains("Move")&&JsonSerializer.Deserialize<WildBattleEvent>(json)==old,"legacy event");
});
Test("disable-struggle-lock-selection-and-same-turn-block",()=>{
 var r=Seeded(seed=>{var s=Pair("DISABLE",seed);return WildBattleRules.ResolveMove(catalog,s with{Opponent=s.Opponent with{LastUsedMove=Move("SPLASH")}},0);},x=>x.Events.OfType<WildBattleDisableChangedEvent>().Any(e=>e.Reason=="move"));var after=Accepted(r);var applied=r.Events.OfType<WildBattleDisableChangedEvent>().First(e=>e.Reason=="move");Check(applied.After is >=2 and <=5&&after.Opponent.DisableTurnsRemaining==applied.After-1,"duration");Check(after.Opponent.Pokemon.Moves[0].CurrentPp==40&&after.Opponent.LastUsedMove is null,"cancelled history/PP");
 var s=Pair("SPLASH");s=s with{Player=s.Player with{DisabledMove=Move("SPLASH"),DisableTurnsRemaining=3},Opponent=s.Opponent with{DisabledMove=Move("SPLASH"),DisableTurnsRemaining=3}};Check(WildBattleRules.RequiresStruggle(s.Player)&&WildBattleRules.IsMoveSelectable(s.Player,-1)&&!WildBattleRules.IsMoveSelectable(s.Player,0),"selection");Atomic(s,WildBattleRules.ResolveMove(catalog,s,0));var both=WildBattleRules.ResolveMove(catalog,s,-1);Accepted(both);Check(both.Events.OfType<WildBattleMoveUsedEvent>().Count(e=>e.Move==WildBattleRules.StruggleMove)==2&&!both.Trace.Any(t=>t.Purpose.Contains("choose-slot")),"disabled choice deadlock");
});
Test("rollout-five-powers-one-pp-and-lock-release",()=>{
 var s=Pair("ROLLOUT");s=s with{Player=s.Player with{AttackStage=0},Opponent=s.Opponent with{DefenseStage=12}};int pp=s.Player.Pokemon.Moves[0].CurrentPp;
 for(int i=0;i<5;i++){var input=s;var r=Seeded(seed=>WildBattleRules.ResolveMove(catalog,input with{Rng=new(seed)},0),x=>x.Events.OfType<WildBattleHpChangedEvent>().Any()&&!x.Events.OfType<WildBattleHpChangedEvent>().First().Critical);s=Accepted(r);var hit=r.Events.OfType<WildBattleHpChangedEvent>().First();int expected=Math.Max(1,((Math.Max(1,(37*2/8)*(30<<i)*10/(45*8/2)/50)+2)/2)*hit.RandomPercent/100);Check(hit.Damage==expected&&s.Player.RolloutTurnsRemaining==4-i&&s.Player.Pokemon.Moves[0].CurrentPp==pp-1,"Rollout source power/timer/PP");Check(WildBattleDamage.Calculate(catalog,input.Player,input.Opponent,Move("ROLLOUT"),false,hit.RandomPercent,profile).Damage==expected,"public dynamic damage");if(i<4)Atomic(s,WildBattleRules.Run(catalog,s));}
 var locked=Pair("ROLLOUT");locked=locked with{Player=locked.Player with{RolloutTurnsRemaining=3,RolloutMoveSlot=0,Pokemon=locked.Player.Pokemon with{Moves=locked.Player.Pokemon.Moves.SetItem(0,locked.Player.Pokemon.Moves[0] with{CurrentPp=0})}}};Check(!WildBattleRules.RequiresStruggle(locked.Player)&&WildBattleRules.IsMoveSelectable(locked.Player,0),"zero PP lock");var disabled=locked with{Player=locked.Player with{DisabledMove=Move("ROLLOUT"),DisableTurnsRemaining=3}};Check(Accepted(WildBattleRules.ResolveMove(catalog,disabled,0)).Player.RolloutTurnsRemaining==0,"disabled Rollout stuck");
 foreach(var reason in new[]{"paralysis","confusion","flinch","infatuation"}){var r=Seeded(seed=>{var x=Pair("ROLLOUT",seed,target:"JIGGLYPUFF");var p=x.Player with{RolloutMoveSlot=0,RolloutTurnsRemaining=3};p=reason switch{"paralysis"=>p with{Status=WildBattleStatus.Paralysis},"confusion"=>p with{ConfusionTurnsRemaining=3},"flinch"=>p with{Flinched=true},_=>p with{InfatuationSource=WildBattleSide.Opponent}};return WildBattleRules.ResolveMove(catalog,x with{Player=p},0);},x=>x.Events.OfType<WildBattleRolloutChangedEvent>().Any(e=>e.Reason==reason));Check(Accepted(r).Player.RolloutTurnsRemaining==0,reason);}
});
