 var poison=Seeded(seed=>WildBattleRules.ResolveMove(catalog,Pair("POUND",seed,target:"NIDORINA"),0),r=>r.Events.OfType<WildBattleStatusChangedEvent>().Any(e=>e.Reason=="poison-point"));Check(Accepted(poison).Player.Status==WildBattleStatus.Poison,"Poison Point");
 var immune=Seeded(seed=>WildBattleRules.ResolveMove(catalog,Pair("POUND",seed,actor:"NIDORINO",target:"NIDORINA"),0),r=>r.Trace.Any(t=>t.Purpose.EndsWith("poison-point")&&t.Result==0));Check(Accepted(immune).Player.Status==0&&!immune.Events.OfType<WildBattleAbilityActivatedEvent>().Any(e=>e.Ability=="ABILITY_POISON_POINT"),"immune false poison event");
 var charm=Seeded(seed=>{var s=Pair("POUND",seed,target:"JIGGLYPUFF");return WildBattleRules.ResolveMove(catalog,s with{Opponent=s.Opponent with{Pokemon=Moves(Mon("JIGGLYPUFF",pid:0),"SPLASH")}},0);},r=>r.Events.OfType<WildBattleInfatuationChangedEvent>().Any());Check(Accepted(charm).Player.InfatuationSource==WildBattleSide.Opponent,"Cute Charm");
 var start=WildBattleRules.Start(catalog,new(Moves(Mon("GYARADOS"),"BITE")),new(Moves(Mon("EKANS"),"WRAP")),new(17),profile);var end=Accepted(start);Check(end.Player.AttackStage==5&&end.Opponent.AttackStage==5&&start.Events.OfType<WildBattleAbilityActivatedEvent>().Count(e=>e.Ability=="ABILITY_INTIMIDATE")==2,"entry Intimidate");
