 var s=Pair("SPLASH",actor:"CHARMANDER");int hp=s.Player.Pokemon.Stats.MaxHp/2;s=s with{Player=s.Player with{HeldItem="ITEM_ORAN_BERRY",Status=WildBattleStatus.Poison,Pokemon=s.Player.Pokemon with{CurrentHp=hp}}};var r=WildBattleRules.ResolveMove(catalog,s,0);var after=Accepted(r);Check(after.Player.HeldItem=="ITEM_NONE"&&r.Events.OfType<WildBattleHeldItemConsumedEvent>().Single().Sequence<r.Events.OfType<WildBattleStatusDamageEvent>().Single().Sequence,"berry timing");
 var crossing=s with{Player=s.Player with{Pokemon=s.Player.Pokemon with{CurrentHp=hp+1}}};Check(Accepted(WildBattleRules.ResolveMove(catalog,crossing,0)).Player.HeldItem=="ITEM_ORAN_BERRY","residual crossing early berry");
 var capture=Pair("SPLASH",target:"JIGGLYPUFF");capture=capture with{Opponent=capture.Opponent with{HeldItem="ITEM_ORAN_BERRY",Status=5,Pokemon=capture.Opponent.Pokemon with{CurrentHp=1}}};var caught=Accepted(WildBattleRules.ResolvePokeBall(catalog,capture));Check(caught.Outcome==WildBattleOutcome.Caught&&caught.Opponent.HeldItem=="ITEM_ORAN_BERRY","capture lost berry");
