Test("independent-source-semantic-RNG-vectors",()=>{
 using var fixture=JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"source-oracle.json")));foreach(var v in fixture.RootElement.GetProperty("traceVectors").EnumerateArray()){string effect=v.GetProperty("effect").GetString()!;uint seed=v.GetProperty("seed").GetUInt32();var s=effect switch{"rollout"=>Pair("ROLLOUT",seed),"double-kick"=>Pair("DOUBLE_KICK",seed,target:"NIDORINA"),_=>Pair("DISABLE",seed)};if(effect=="disable")s=s with{Opponent=s.Opponent with{LastUsedMove=Move("SPLASH")}};var r=WildBattleRules.ResolveMove(catalog,s,0);var end=Accepted(r);var expected=v.GetProperty("trace").EnumerateArray().ToArray();Check(r.Trace.Length==expected.Length,"draw count");for(int i=0;i<expected.Length;i++){var t=r.Trace[i];var e=expected[i];Check(t.Purpose==e.GetProperty("purpose").GetString()&&t.Before==e.GetProperty("before").GetUInt32()&&t.After==e.GetProperty("after").GetUInt32()&&t.Raw==e.GetProperty("raw").GetUInt16()&&t.Bound==e.GetProperty("bound").GetInt32()&&t.Result==e.GetProperty("result").GetInt32(),effect+" source draw "+i);}if(effect=="rollout")Check(end.Player.RolloutTurnsRemaining==v.GetProperty("remaining").GetInt32(),"rollout timer");if(effect=="disable")Check(end.Opponent.DisableTurnsRemaining==v.GetProperty("remaining").GetInt32(),"disable timer");}
});
